<div class="adm-table-wrap" style="background:#fff;border:1px solid #ececec;border-radius:12px"><table class="tcm-table"><thead><tr><th>Partner</th><th>Type / Subject</th><th>Details</th><th>Status</th><th>Update</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="5">No requests.</td></tr><?php endif ?><?php foreach($rows as $r): ?><tr><td><?= e($r['display_name']) ?><br><?= e($r['submitted_by']) ?></td><td><?= e($r['request_type']) ?><br><strong><?= e($r['subject']) ?></strong></td><td><?= e($r['details']) ?></td><td><?= e(str_replace('_',' ',$r['status'])) ?><br><?= e($r['admin_note']??'') ?></td><td><form method="post" action="<?= base_url('/admin/partners/requests/'.$r['id']) ?>"><?= csrf_field() ?><select class="form-select form-select-sm" name="status"><option>under_review</option><option>additional_information</option><option>shortlisted</option><option>demo_scheduled</option><option>mentor_assigned</option><option>approved</option><option>rejected</option><option>scheduled</option><option>completed</option><option>in_progress</option><option>waiting_partner</option><option>resolved</option><option>closed</option></select><input class="form-control form-control-sm mt-1" name="admin_note" placeholder="Update note"><button class="tcm-btn primary sm mt-1">Save</button></form></td></tr><?php endforeach ?></tbody></table></div>
